// Do not edit this file as it will be overwritten if HAMR codegen is rerun
@msig trait PresentationDecisionOwner_coordination_presentation_decision_TestApi {

  def BeforeEntrypoint(): Unit = {
    Art.initTest(Arch.EITImageAvailabilitySystem_Instance_coordination_presentation_decision)
  }

  def AfterEntrypoint(): Unit = {
    Art.finalizeTest(Arch.EITImageAvailabilitySystem_Instance_coordination_presentation_decision)
  }

  def testCompute(): Unit = {
    Art.manuallyClearOutput()
    Art.testCompute(Arch.EITImageAvailabilitySystem_Instance_coordination_presentation_decision)
  }

  def testInitialise(): Unit = {
    Art.manuallyClearOutput()
    Art.testInitialise(Arch.EITImageAvailabilitySystem_Instance_coordination_presentation_decision)
  }

  /** helper function to set the values of all input ports.
   * @param availabilityFrame payload for data port availabilityFrame
   * @param reviewFrame payload for data port reviewFrame
   */
  def put_concrete_inputs(availabilityFrame : EIT_Image_Availability_Coordinator.AvailabilityDecisionFrame,
                          reviewFrame : EIT_Image_Availability_Coordinator.ReviewFrame): Unit = {
    put_availabilityFrame(availabilityFrame)
    put_reviewFrame(reviewFrame)
  }


  /** helper function to check PresentationDecisionOwner_coordination_presentation_decision's
   * output ports.  Use named arguments to check subsets of the output ports.
   * @param presentationFrame method that will be called with the value of the outgoing data
   *        port 'presentationFrame'.
   */
  def check_concrete_output(presentationFrame: EIT_Image_Availability_Coordinator.PresentationFrame => B): Unit = {
    var testFailures: ISZ[ST] = ISZ()

    val presentationFrameValue: EIT_Image_Availability_Coordinator.PresentationFrame = get_presentationFrame().get
    if(!presentationFrame(presentationFrameValue)) {
      testFailures = testFailures :+ st"'presentationFrame' did not match expected: value of the outgoing data port is ${presentationFrameValue}"
    }

    assert(testFailures.isEmpty, st"${(testFailures, "\n")}".render)
  }


  // setter for in DataPort
  def put_availabilityFrame(value : EIT_Image_Availability_Coordinator.AvailabilityDecisionFrame): Unit = {
    Art.insertInInfrastructurePort(Arch.EITImageAvailabilitySystem_Instance_coordination_presentation_decision.operational_api.availabilityFrame_Id, EIT_Image_Availability_Coordinator.AvailabilityDecisionFrame_Payload(value))
  }

  // setter for in DataPort
  def put_reviewFrame(value : EIT_Image_Availability_Coordinator.ReviewFrame): Unit = {
    Art.insertInInfrastructurePort(Arch.EITImageAvailabilitySystem_Instance_coordination_presentation_decision.operational_api.reviewFrame_Id, EIT_Image_Availability_Coordinator.ReviewFrame_Payload(value))
  }

  // getter for out DataPort
  def get_presentationFrame(): Option[EIT_Image_Availability_Coordinator.PresentationFrame] = {
    val value: Option[EIT_Image_Availability_Coordinator.PresentationFrame] = get_presentationFrame_payload() match {
      case Some(EIT_Image_Availability_Coordinator.PresentationFrame_Payload(v)) => Some(v)
      case Some(v) => halt(s"Unexpected payload on port presentationFrame.  Expecting 'EIT_Image_Availability_Coordinator.PresentationFrame_Payload' but received ${v}")
      case _ => None[EIT_Image_Availability_Coordinator.PresentationFrame]()
    }
    return value
  }

  // payload getter for out DataPort
  def get_presentationFrame_payload(): Option[EIT_Image_Availability_Coordinator.PresentationFrame_Payload] = {
    return Art.observeOutInfrastructurePort(Arch.EITImageAvailabilitySystem_Instance_coordination_presentation_decision.initialization_api.presentationFrame_Id).asInstanceOf[Option[EIT_Image_Availability_Coordinator.PresentationFrame_Payload]]
  }

}
